import{_ as r,o as a,c as e,a2 as o}from"./chunks/framework.A5mep7Fe.js";const g=JSON.parse('{"title":"🧭 00 · 导论与学习哲学","description":"","frontmatter":{},"headers":[],"relativePath":"00-导论与学习哲学/index.md","filePath":"00-导论与学习哲学/README.md","lastUpdated":1786806808000}'),n={name:"00-导论与学习哲学/index.md"};function l(i,t,s,d,h,c){return a(),e("div",null,[...t[0]||(t[0]=[o('<h1 id="🧭-00-·-导论与学习哲学" tabindex="-1">🧭 00 · 导论与学习哲学 <a class="header-anchor" href="#🧭-00-·-导论与学习哲学" aria-label="Permalink to &quot;🧭 00 · 导论与学习哲学&quot;">​</a></h1><blockquote><p>本篇是本项目的「灵魂篇」，也是与市面上绝大多数面试八股资料最根本的区别所在。 不读这一篇，你只是在「背题」；读完这一篇，你才开始「建立判断力」。</p></blockquote><hr><h2 id="为什么需要「学习哲学」" tabindex="-1">为什么需要「学习哲学」？ <a class="header-anchor" href="#为什么需要「学习哲学」" aria-label="Permalink to &quot;为什么需要「学习哲学」？&quot;">​</a></h2><p>过去十年，AI 领域出现了多次「范式切换」：</p><ul><li>2012 年 AlexNet 引爆深度学习 → 2017 年 Transformer 统一序列建模 →</li><li>2018-2020 年 BERT/GPT 预训练范式 → 2022 年 ChatGPT 引爆大模型 →</li><li>2023-2024 年 多模态 / Agent / RAG 爆发 → 2025+ 年 推理模型 / Agentic RL / 世界模型。</li></ul><p><strong>每一轮切换，都会让上一轮「背得最熟的人」部分过时。</strong> 如果你只会背当前热点，你永远在追尾巴。</p><p>所以本项目反其道而行：<strong>教你在任何一轮技术浪潮中，都能快速判断「这个技术值不值得投入、投入多久、学到什么深度」。</strong> 这套判断力，比任何单一知识点都保值。</p><hr><h2 id="本篇包含" tabindex="-1">本篇包含 <a class="header-anchor" href="#本篇包含" aria-label="Permalink to &quot;本篇包含&quot;">​</a></h2><table tabindex="0"><thead><tr><th>文档</th><th>解决的核心问题</th></tr></thead><tbody><tr><td><a href="./01-AI技术本质判断">01-AI技术本质判断</a></td><td>面对一个新 AI 概念，如何 30 分钟判断它是否值得长期投入？</td></tr><tr><td><a href="./02-跨周期价值技术地图">02-跨周期价值技术地图</a></td><td>哪些技术已被多界验证、具备跨周期价值？哪些是观察期热点？</td></tr><tr><td><a href="./03-学习路线总览">03-学习路线总览</a></td><td>不同背景/目标的人，分别该怎么学、学到什么程度、多久能上岸？</td></tr></tbody></table><hr><h2 id="三条元原则-贯穿全书" tabindex="-1">三条元原则（贯穿全书） <a class="header-anchor" href="#三条元原则-贯穿全书" aria-label="Permalink to &quot;三条元原则（贯穿全书）&quot;">​</a></h2><ol><li><p><strong>第一性原则（First Principles）</strong> 任何技术都问：它<strong>到底在优化什么目标函数/解决什么瓶颈</strong>？一旦你能用一句话说清它的「问题-方案-代价」，你就真的懂了，也忘不掉。</p></li><li><p><strong>可迁移优先（Transferable First）</strong> 优先学<strong>十年后还在用</strong>的东西：数学基础、概率论、优化理论、分布式系统、软件工程、系统设计、对「误差与不确定性」的直觉。这些是换任何技术栈都不作废的资产。</p></li><li><p><strong>产出导向（Output-Oriented）</strong> 学一个技术，立刻用它做点东西（代码/项目/文章）。<strong>没有产出的学习，90% 会忘。</strong> 本项目每个模块都配套「动手清单」。</p></li></ol><hr><h2 id="给不同读者的开场白" tabindex="-1">给不同读者的开场白 <a class="header-anchor" href="#给不同读者的开场白" aria-label="Permalink to &quot;给不同读者的开场白&quot;">​</a></h2><ul><li><strong>如果你是学生/转行小白</strong>：别焦虑。AI 行业最稀缺的不是「什么都会的人」，而是「能把一件事做扎实的人」。从 <code>03-学习路线</code> 找到你的起点。</li><li><strong>如果你是科班研究生冲算法岗</strong>：你的护城河是<strong>深度</strong>。把 <code>01-LLM</code> 和 <code>04-传统深度学习</code> 的推导啃透，比刷 100 道浅题有用。</li><li><strong>如果你是工程师转 AI 应用开发</strong>：你的机会在「落地」。算法岗卷不过博士，但能把模型变成稳定、低成本、可监控产品的工程师极稀缺。重点看 <code>08-AI应用开发</code>。</li><li><strong>如果你已工作想规划长期路线</strong>：直接看 <code>10-职业发展与资源</code>。</li></ul><hr><p>➡️ 下一步：<a href="./01-AI技术本质判断">01-AI技术本质判断</a></p>',19)])])}const u=r(n,[["render",l]]);export{g as __pageData,u as default};
